const entrada = $input.first().json;
let texto = '';

// Extraemos el texto de forma segura sin importar la estructura de Anthropic
if (entrada.content && Array.isArray(entrada.content)) {
  const bloqueTexto = entrada.content.find(c => c.type === 'text');
  texto = bloqueTexto ? (bloqueTexto.text ?? '') : '';
} else if (entrada.content && entrada.content.text) {
  texto = entrada.content.text;
} else if (entrada.text) {
  texto = entrada.text;
}

// Limpiamos los bloques de formato markdown si la IA los incluyó
texto = texto.replace(/```json/gi, '').replace(/```/g, '').trim();

let ai;
try {
  ai = JSON.parse(texto);
} catch (e) {
  throw new Error('IA 1 no devolvio un JSON valido: ' + texto.slice(0, 200));
}

if (typeof ai.es_consulta_valida !== 'boolean') {
  throw new Error('IA 1: falta es_consulta_valida');
}

if (ai.es_consulta_valida) {
  const requeridas = ['tipo_consulta', 'aplicacion', 'superficie', 'quiere_colocacion', 'datos_faltantes', 'pide_envio'];
  const faltan = requeridas.filter(k => !(k in ai));
  if (faltan.length) throw new Error('IA 1: faltan claves: ' + faltan.join(', '));
}

return [{ json: ai }];

const ai   = $('Parsear respuesta de IA').first().json;
const base = $('Preparar datos para la IA').first().json;
const t    = $('Leer Tarifas').first().json.fields;
const sup  = $('Leer Superficies').all().map(i => i.json.fields);

// --- Tarifas: todo se lee de Airtable
const precioPanel      = Number(t.Precio_panel_m2);
const precioColocacion = Number(t.Precio_colocacion_m2);
const alturaMaxima     = Number(t.Altura_maxima_m);
const alturas = String(t.Alturas_disponibles_m).split(';').map(Number).filter(n => n > 0).sort((a, b) => a - b);
const modulo  = Math.min(...String(t.Modulos_ancho_m).split(';').map(Number).filter(n => n > 0));
if (!precioPanel || !alturaMaxima || !alturas.length || !isFinite(modulo)) {
  throw new Error('Tarifas incompletas o con formato invalido en Airtable');
}

// --- Datos de la consulta
const tieneFoto = base.tiene_foto === true || base.tiene_foto === 'true';
const quiereColocacion = ai.quiere_colocacion === true;
const altoM  = ai.alto_m  != null ? Number(ai.alto_m)  : null;
const anchoM = ai.ancho_m != null ? Number(ai.ancho_m) : null;

// --- Escenario: se aplica el primero que se cumple
let escenario = 'COTIZACION';
if (ai.es_consulta_valida === false) escenario = 'DESCARTE';
else if (altoM > alturaMaxima) escenario = 'ALTURA_FUERA_DE_RANGO';
else if (ai.superficie === 'No contemplada') escenario = 'SUPERFICIE_NO_CONTEMPLADA';
else if (ai.tipo_consulta === 'Viabilidad' && ai.superficie !== 'No especifica') escenario = 'SOLO_VIABILIDAD';
else if (!altoM || !anchoM || ai.superficie === 'No especifica') escenario = 'FALTAN_MEDIDAS';

// --- Cotizacion
let altoCot = null, anchoCot = null, m2 = null;
let paneles = 0, colocacion = 0, total = 0;
if (escenario === 'COTIZACION') {
  altoCot = alturas.find(a => a >= altoM);
  if (altoCot === undefined) throw new Error('No hay una altura disponible para ' + altoM + ' m');
  anchoCot = Math.ceil(+(anchoM / modulo).toFixed(6)) * modulo;
  m2 = altoCot * anchoCot;
  paneles = m2 * precioPanel;
  if (quiereColocacion) colocacion = m2 * precioColocacion;
  total = paneles + colocacion;
}

// --- Foto y datos faltantes
const faltaFoto = escenario === 'COTIZACION' && quiereColocacion && !tieneFoto;
const faltantes = Array.isArray(ai.datos_faltantes) ? [...ai.datos_faltantes] : [];
if (quiereColocacion && !tieneFoto && !faltantes.includes('foto')) faltantes.push('foto');

// --- Envio: externo si pide envio y el destino no es la ciudad base
const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const ciudadBase = norm(String(base.ciudad_base).split(',')[0]);
const destino = norm(ai.ciudad_destino);
const envioExterno = ai.pide_envio === true && (destino === '' || !destino.includes(ciudadBase));

// --- Condicion de colocacion de la superficie elegida
const fila = sup.find(s => s.Superficie === ai.superficie);
const condicion = fila ? (fila.Condicion_de_colocacion ?? '') : '';

const pesos = n => '$' + Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');

return [{ json: {
  ...base,
  escenario,
  tipo_consulta: ai.tipo_consulta ?? null,
  resumen: ai.resumen ?? '',
  motivo_descarte: ai.motivo_descarte ?? null,
  superficie: ai.superficie ?? null,
  aplicacion: ai.aplicacion ?? null,
  quiere_colocacion: quiereColocacion,
  pide_envio: ai.pide_envio === true,
  envio_externo: envioExterno,
  ciudad_destino: ai.ciudad_destino ?? '',
  falta_foto: faltaFoto,
  condicion_de_colocacion: condicion,
  datos_faltantes: faltantes.join(', '),
  alto_pedido_m: altoM,
  ancho_pedido_m: anchoM,
  alto_cotizado_m: altoCot,
  ancho_cotizado_m: anchoCot,
  m2_cotizados: m2,
  importe_paneles: paneles,
  importe_colocacion: colocacion,
  importe_total: total,
  importe_paneles_texto: pesos(paneles),
  importe_colocacion_texto: pesos(colocacion),
  importe_total_texto: pesos(total),
  altura_maxima_m: alturaMaxima,
  transportista: t.Transportista_envios ?? ''
} }];

