// 1. Buscamos el texto dentro de la estructura nativa de Anthropic Claude
const entrada = $('IA 2 · Redactar respuesta').first().json;
let bruto = "";

if (entrada.content && Array.isArray(entrada.content)) {
  // Si el bloque 0 es thinking, leemos el bloque 1 que contiene el texto
  bruto = entrada.content[1]?.text || entrada.content[0]?.text || "";
} else if (entrada.content && entrada.content.text) {
  bruto = entrada.content.text;
}

// 2. Limpiamos bloques de código markdown si la IA los incluyó
const limpio = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();

let r;
try { 
  r = JSON.parse(limpio); 
} catch (e) { 
  throw new Error('IA 2 no devolvio un JSON valido: ' + bruto.slice(0, 200)); 
}

// 3. Validamos que contenga las dos claves obligatorias para el negocio
if (!r.asunto_respuesta || !r.cuerpo_respuesta) {
  throw new Error('Faltan asunto_respuesta o cuerpo_respuesta en el JSON de la IA 2');
}

return [{ 
  json: { 
    asunto_respuesta: r.asunto_respuesta, 
    cuerpo_respuesta: r.cuerpo_respuesta 
  } 
}];

